// swift-tools-version: 6.0
import PackageDescription

// The app itself (Live Activity host + widget extension) is built by Notchbot.xcodeproj, generated by
// scripts/gen_xcodeproj.py, because ActivityKit on macOS needs the macOS 27.3 SDK and a widget extension.
// SwiftPM builds and tests everything that is pure logic.
let package = Package(
    name: "notchbot",
    platforms: [.macOS(.v14)],
    products: [
        .library(name: "NotchbotCore", targets: ["NotchbotCore"]),
        .executable(name: "notchbot-hook", targets: ["notchbot-hook"]),
    ],
    targets: [
        .target(name: "NotchbotCore"),
        .executableTarget(name: "notchbot-hook", dependencies: ["NotchbotCore"]),
        .testTarget(name: "NotchbotCoreTests", dependencies: ["NotchbotCore"]),
    ]
)
